import '../../core/api/api_client.dart';

class NotificationsApi {
  NotificationsApi(this.client);
  final ApiClient client;
  Future<NotificationResponse> list({bool unreadOnly = false}) async => NotificationResponse.fromJson(await client.get('/api/v1/notifications', query: {'page': '1', if (unreadOnly) 'unread_only': 'true'}));
  Future<void> markRead(String id) async { await client.patch('/api/v1/notifications/$id/read'); }
  Future<NotificationPreferences> preferences() async => NotificationPreferences.fromJson(await client.get('/api/v1/notification-preferences'));
  Future<NotificationPreferences> updatePreferences(NotificationPreferences value) async => NotificationPreferences.fromJson(await client.patch('/api/v1/notification-preferences', body: {
    'dnd_enabled': value.dndEnabled, 'dnd_start': value.dndStart, 'dnd_end': value.dndEnd,
    'categories': {for (final item in value.categories) item.category: item.isRequired ? true : item.enabled},
  }));
}
class NotificationResponse { const NotificationResponse(this.count, this.unreadCount, this.items); final int count; final int unreadCount; final List<PatientNotification> items; factory NotificationResponse.fromJson(Map<String,dynamic> json) => NotificationResponse((json['count'] as num?)?.toInt() ?? 0, (json['unread_count'] as num?)?.toInt() ?? 0, (json['results'] as List? ?? const []).whereType<Map>().map(PatientNotification.fromJson).toList()); }
class PatientNotification { const PatientNotification({required this.id, required this.category, required this.severity, required this.title, required this.body, required this.isRead, required this.createdAt}); final String id, category, severity, title, body; final bool isRead; final DateTime? createdAt; factory PatientNotification.fromJson(Map<dynamic,dynamic> json) => PatientNotification(id: json['id']?.toString() ?? '', category: json['category']?.toString() ?? '', severity: json['severity']?.toString() ?? '', title: json['title']?.toString() ?? '', body: json['body']?.toString() ?? '', isRead: json['is_read'] == true, createdAt: DateTime.tryParse(json['created_at']?.toString() ?? '')); }
class NotificationPreferences { const NotificationPreferences({required this.dndEnabled, required this.dndStart, required this.dndEnd, required this.categories}); final bool dndEnabled; final String? dndStart, dndEnd; final List<NotificationCategoryPreference> categories; factory NotificationPreferences.fromJson(Map<String,dynamic> json) { final dnd=json['dnd'] is Map?Map<String,dynamic>.from(json['dnd']):<String,dynamic>{}; return NotificationPreferences(dndEnabled:dnd['enabled']==true||dnd['dnd_enabled']==true,dndStart:(dnd['start']??dnd['dnd_start'])?.toString(),dndEnd:(dnd['end']??dnd['dnd_end'])?.toString(),categories:(json['categories'] as List? ?? const []).whereType<Map>().map(NotificationCategoryPreference.fromJson).toList()); } NotificationPreferences toggle(String category,bool enabled)=>NotificationPreferences(dndEnabled:dndEnabled,dndStart:dndStart,dndEnd:dndEnd,categories:categories.map((item)=>item.category==category?item.copyWith(enabled:enabled):item).toList()); }
class NotificationCategoryPreference { const NotificationCategoryPreference({required this.category,required this.enabled,required this.isRequired}); final String category; final bool enabled,isRequired; factory NotificationCategoryPreference.fromJson(Map<dynamic,dynamic> json){final category=json['category']?.toString()??'';return NotificationCategoryPreference(category:category,enabled:json['enabled']==true,isRequired:json['required']==true||category.toUpperCase()=='CRITICAL');} NotificationCategoryPreference copyWith({bool? enabled})=>NotificationCategoryPreference(category:category,enabled:enabled??this.enabled,isRequired:isRequired); }
